 66	
 67	  /* Bat BTA flow control tren DSI Host */
 68	  HAL_DSI_ConfigFlowControl(&hdsi_eval, DSI_FLOW_CONTROL_BTA);
 69	
 70	  /* 0x11: Sleep Out */
 71	  g_dsi_write_ret[0] = (uint32_t)HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x11, 0x00);
 72	  HAL_Delay(120);
 73	  /* 0x51: WRDISBV - dat do sang toi da (0xFF) */
