 77	  /* 0x29: Display On */
 78	  g_dsi_write_ret[3] = (uint32_t)HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x29, 0x00);
 79	  HAL_Delay(50);
 80	
 81	  /* Doc cac thanh ghi trang thai DCS cua panel va luu ma tra ve */
 82	  g_panel_read_ret[0] = DSI_IO_ReadCmd(0xDA, (uint8_t *)&g_panel_status[0], 1); g_panel_dcs[0] = g_panel_status[0]; /* ID1 */
 83	  g_panel_read_ret[1] = DSI_IO_ReadCmd(0x0A, (uint8_t *)&g_panel_status[1], 1); g_panel_dcs[1] = g_panel_status[1]; /* Power Mode */
 84	  g_panel_read_ret[2] = DSI_IO_ReadCmd(0x0B, (uint8_t *)&g_panel_status[2], 1); g_panel_dcs[2] = g_panel_status[2]; /* MADCTL */
 85	  g_panel_read_ret[3] = DSI_IO_ReadCmd(0x0C, (uint8_t *)&g_panel_status[3], 1); g_panel_dcs[3] = g_panel_status[3]; /* COLMOD */
 86	  g_panel_read_ret[4] = DSI_IO_ReadCmd(0x52, (uint8_t *)&g_panel_status[4], 1); g_panel_dcs[4] = g_panel_status[4]; /* Brightness */
 87	  g_panel_read_ret[5] = DSI_IO_ReadCmd(0x54, (uint8_t *)&g_panel_status[5], 1); g_panel_dcs[5] = g_panel_status[5]; /* CTRL Display */
 88	  g_panel_read_ret[6] = DSI_IO_ReadCmd(0x0F, (uint8_t *)&g_panel_status[6], 1); g_panel_dcs[6] = g_panel_status[6]; /* Self-Diagnostic */
 89	  g_panel_read_ret[7] = DSI_IO_ReadCmd(0x0D, (uint8_t *)&g_panel_status[7], 1); g_panel_dcs[7] = g_panel_status[7]; /* Image Mode */
