155	static void DrawLogo(uint32_t x0, uint32_t y0)
156	{
157	  for (uint32_t y = 0; y < LOGO_PTIT_HEIGHT; y++)
158	  {
159	    for (uint32_t x = 0; x < LOGO_PTIT_WIDTH; x++)
160	    {
161	      uint32_t pixel = logo_ptit_data[y * LOGO_PTIT_WIDTH + x];
162	      uint8_t a = (pixel >> 24) & 0xFF;
163	      if (a > 0)
164	      {
165	        if (a == 255)
166	        {
167	          BSP_LCD_DrawPixel(x0 + x, y0 + y, pixel);
168	        }
169	        else
170	        {
171	          uint32_t r = (pixel >> 16) & 0xFF;
172	          uint32_t g = (pixel >> 8) & 0xFF;
173	          uint32_t b = pixel & 0xFF;
174	          r = (r * a + 255 * (255 - a)) / 255;
175	          g = (g * a + 255 * (255 - a)) / 255;
176	          b = (b * a + 255 * (255 - a)) / 255;
177	          BSP_LCD_DrawPixel(x0 + x, y0 + y, 0xFF000000UL | (r << 16) | (g << 8) | b);
178	        }
179	      }
180	    }
181	  }
182	}
