271	    HAL_Delay(120);
272	    HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x51, 0xFF); /* WRDISBV */
273	    HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x53, 0x2C); /* WRCTRLD */
274	    HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x29, 0x00); /* Display On */
275	    HAL_Delay(50);
276	
277	    /* Doc cac thanh ghi DCS cua panel OTM8009A */
278	    g_panel_cmd_ret[0] = DSI_IO_ReadCmd(0xDA, (uint8_t *)&g_panel_cmd_status[0], 1); /* ID1 (0x80) */
279	    g_panel_cmd_ret[1] = DSI_IO_ReadCmd(0x0A, (uint8_t *)&g_panel_cmd_status[1], 1); /* Power Mode */
280	    g_panel_cmd_ret[2] = DSI_IO_ReadCmd(0x0B, (uint8_t *)&g_panel_cmd_status[2], 1); /* MADCTL */
281	    g_panel_cmd_ret[3] = DSI_IO_ReadCmd(0x0C, (uint8_t *)&g_panel_cmd_status[3], 1); /* COLMOD */
282	    g_panel_cmd_ret[4] = DSI_IO_ReadCmd(0x52, (uint8_t *)&g_panel_cmd_status[4], 1); /* Brightness */
283	    g_panel_cmd_ret[5] = DSI_IO_ReadCmd(0x54, (uint8_t *)&g_panel_cmd_status[5], 1); /* CTRL Display */
284	    g_panel_cmd_ret[6] = DSI_IO_ReadCmd(0x0F, (uint8_t *)&g_panel_cmd_status[6], 1); /* Self-Diagnostic */
285	    g_panel_cmd_ret[7] = DSI_IO_ReadCmd(0x0D, (uint8_t *)&g_panel_cmd_status[7], 1); /* Image Mode */
