303	    lcd_y_size = OTM8009A_800X480_HEIGHT; /* 480 */                                
304	  }

410	    OTM8009ACtx.Orientation = OTM8009A_ORIENTATION_LANDSCAPE;
411	  }
412	  else
413	  {
414	    OTM8009ACtx.Orientation = OTM8009A_ORIENTATION_PORTRAIT;
