423	  /* defaut is 0, try 0x2C - Brightness Control Block, Display Dimming & BackLight on */
424	  ret += otm8009a_write_reg(&pObj->Ctx, OTM8009A_CMD_WRCTRLD, &short_reg_data[40], 0);
425	  
426	  /* defaut is 0, try 0x02 - image Content based Adaptive Brightness [Still Picture] */
427	  ret += otm8009a_write_reg(&pObj->Ctx, OTM8009A_CMD_WRCABC, &short_reg_data[41], 0);
428	  
429	  /* defaut is 0 (lowest Brightness], 0xFF is highest Brightness */
430	  ret += otm8009a_write_reg(&pObj->Ctx, OTM8009A_CMD_WRCABCMB, &short_reg_data[42], 0);
431	  
432	  /** CABC : Content Adaptive Backlight Control section end << */
433	  
434	  /* Send Command Display On */
435	  ret += otm8009a_write_reg(&pObj->Ctx, OTM8009A_CMD_DISPON, &short_reg_data[43], 0);
