HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x11, 0x00); /* Sleep Out */
HAL_Delay(120);

/* Phep thu phan dinh do sang: doc ban dau, ghi 0x88, doc lai */
extern volatile uint8_t  g_bright_before;
extern volatile uint8_t  g_bright_val_written;
extern volatile uint8_t  g_bright_after;
extern volatile uint32_t g_bright_write_ret;
extern volatile int32_t  g_bright_read_ret;

/* Doc gia tri do sang ban dau truoc khi ghi */
DSI_IO_ReadCmd(0x52, (uint8_t *)&g_bright_before, 1);

/* Ghi gia tri do sang test moi (0x88) */
g_bright_val_written = 0x88;
g_bright_write_ret = (uint32_t)HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x51, g_bright_val_written); /* WRDISBV */
HAL_Delay(10);

/* Doc lai dung thanh ghi do sang 0x52 ngay sau khi ghi */
g_bright_read_ret = DSI_IO_ReadCmd(0x52, (uint8_t *)&g_bright_after, 1);

HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x53, 0x2C); /* WRCTRLD */
HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x29, 0x00); /* Display On */
HAL_Delay(50);

